import { PgUserDao } from './dao/pg-user-dao.js';
import { MongoUserDao } from './dao/mongo-user-dao.js';

const implementations = {
  postgres: (cfg) => new PgUserDao(cfg.pool),
  mongo:    (cfg) => new MongoUserDao(cfg.client),
};

export function createUserDao(store, cfg) {
  const make = implementations[store];
  if (!make) throw new Error(`unknown store: ${store}`);
  return make(cfg);
}
